 const proofBytes=Buffer.from(JSON.stringify(proof)),zipSHA256='9'.repeat(64),name='pr356-'+phaseId+'-'+runId+'-'+attempt,expected={runId,attempt,jobId:String(jobId),artifactId:String(artifactId),artifactName:name,zipSHA256,zipBytes:1000,sourceHead:H};
 const run={id:Number(runId),run_attempt:Number(attempt),head_sha:H,head_branch:BRANCH,event:'workflow_dispatch',path:'.github/workflows/ci.yml',repository:{full_name:REPOSITORY},head_repository:{full_name:REPOSITORY},conclusion:null};
 const job={id:jobId,run_id:Number(runId),run_attempt:Number(attempt),head_sha:H,name:p.jobName,status:'completed',conclusion:'success',completed_at:completedAt,steps:[]};
 const artifact={id:artifactId,name,expired:false,expires_at:new Date(Date.now()+3600000).toISOString(),size_in_bytes:1000,digest:'sha256:'+zipSHA256,workflow_run:{id:Number(runId),head_sha:H}};
