 const mf=readySarifFixture('postmerge'),mp=mf.make(),rawA=Buffer.from(JSON.stringify(admission)),aBundle=aggregateBundle(mp,'merge-admission',rawA,'1002'),official=verifyOfficialAdmission({plan:mp,...aBundle,receiptBytes:rawA});const reused=verifyMainReuse({plan:mp,officialAdmission:official,qualification:admittedQ});assert.equal(reused.main,A);assert.equal(reused.buildRepeated,false);assert.equal(reused.checksRepeated,false);assert.throws(()=>verifyMainReuse({plan:mp,officialAdmission:official}),/freshly verify/);
